+            float range=Vector3.Distance(hit.position,target);
+            float score=(clear?30:0)-Mathf.Abs(range-12)-travel*.12f;
+            if(score<=best)continue;best=score;position=hit.position;found=true;
+        }
+        return found;
+    }
